{"results": [{"id": "FAM:SF-APPA-001", "label": "Study family SF-APPA-001: A1 adaptation falsification: asymmetry, confidence and carryover tests", "score": 1.408, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-001 (0.73)", "FAM:SF-APPS-058 auto_related_family (limitation_precedent) FAM:SF-APPA-001"], "attributes": {"observed_research_question": "A1 adaptation falsification: asymmetry, confidence and carryover tests", "auto_outcome_status": "artifact", "observed_hypothesis": "If the A1 adapter PPP lift is real coverage response, wrong-way teams should do worse than no-signal teams, the gap should widen with scheme-vote confidence, and adapting in Game N should carry over to Game N+1.", "observed_result": "T1 dPPP: adapter +0.0667 (n=205), neutral +0.0248 (n=50), no_signal +0.1260 (n=57), wrong_way +0.0111 (n=274). T2: adapter minus no-signal -0.0361 (1 vote), -0.1170 (2 votes). T3 next-game PPP Welch t=-1.003, p=0.842; MW [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}, {"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}]}, {"id": "FAM:SF-APPS-058", "label": "Study family SF-APPS-058: Observed on-ball defensive scheme labels (ORL-DET G1)", "score": 1.11, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-058 (0.74)", "FAM:SF-APPA-001 auto_related_family (limitation_precedent) FAM:SF-APPS-058"], "attributes": {"observed_research_question": "Observed on-ball defensive scheme labels (ORL-DET G1)", "auto_outcome_status": "untestable", "observed_hypothesis": "NBA matchup/PBP fields can label on-ball coverage (DROP/ICE/SWITCH) at usable rates.", "observed_result": "DET: 67 on-ball HC poss, 10